def semver_sort(versions):
    import functools

    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = map(int, main.split('.'))
        return (major, minor, patch, pre)

    def cmp_pre(a, b):
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        a_ids = a.split('.')
        b_ids = b.split('.')
        for ai, bi in zip(a_ids, b_ids):
            a_num = ai.isdigit()
            b_num = bi.isdigit()
            if a_num and b_num:
                ai_v, bi_v = int(ai), int(bi)
                if ai_v != bi_v:
                    return -1 if ai_v < bi_v else 1
            elif a_num and not b_num:
                return -1
            elif not a_num and b_num:
                return 1
            else:
                if ai != bi:
                    return -1 if ai < bi else 1
        if len(a_ids) != len(b_ids):
            return -1 if len(a_ids) < len(b_ids) else 1
        return 0

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

